svg.script:
"use strict";
// The launcher's own copy. The game itself never fetches anything: this page is
// the one that downloads horizon.html, stores it in IndexedDB and lets the
// worker serve it with the headers that enable the game's threads.
var Q = new URLSearchParams(location.search);
var GAME = "horizon.html";
var DRIVE_ID = "1o_7XgQ39hX1HHayNF9pLmzn0bbPqRWov";
var DRIVE_KEY = "AIzaSyC5HrSEXwPdoHF3jCvp6gUwzCCyjc6Mimo";
var DRIVE_URL = "https://www.googleapis.com/drive/v3/files/" + encodeURIComponent(DRIVE_ID) + "?alt=media&key=" + encodeURIComponent(DRIVE_KEY);
var SOURCE = Q.get("src") ? new URL(Q.get("src"), location.href).href : DRIVE_URL;
var SW_URL = "horizon-launch-sw.js";
var SW_BUILD = "02ac2ab32d40";
var DB_NAME = "horizon-launcher";
var DB_VERSION = 1;
var CHUNK = 4 << 20;
var busy = false;

var SVGNS = "http://www.w3.org/2000/svg";

function el(id) { return document.getElementById(id); }
function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

// SVG has no text flow, so each label is wrapped into tspans by its own column
// budget: the source URL and the failure messages are sentences, not labels.
function wrap(text, cols, maxLines) {
  var words = String(text == null ? "" : text).split(/\s+/), out = [], cur = "", truncated = false;
  for (var i = 0; i < words.length; i++) {
    var word = words[i];
    if (!word) continue;
    if (!cur) {
      cur = word;
    } else if ((cur + " " + word).length <= cols) {
      cur += " " + word;
    } else {
      if (out.length === maxLines - 1) { truncated = true; break; }
      out.push(cur);
      cur = word;
    }
    if (cur.length > cols) cur = cur.slice(0, cols);
  }
  if (cur && out.length < maxLines) out.push(cur);
  if (!out.length) out.push("");
  if (truncated) {
    var last = out[out.length - 1];
    out[out.length - 1] = (last.length > cols - 1 ? last.slice(0, cols - 1) : last) + "\u2026";
  }
  return out;
}

function writeLines(id, text) {
  var node = el(id);
  var cols = Number(node.getAttribute("data-cols") || 64);
  var dy = Number(node.getAttribute("data-dy") || 22);
  var y0 = Number(node.getAttribute("data-y") || node.getAttribute("y") || 0);
  var maxLines = Number(node.getAttribute("data-max") || 2);
  while (node.firstChild) node.removeChild(node.firstChild);
  var lines = wrap(text, cols, maxLines);
  for (var i = 0; i < lines.length; i++) {
    var line = document.createElementNS(SVGNS, "tspan");
    line.setAttribute("x", node.getAttribute("x"));
    line.setAttribute("y", String(y0 + i * dy));
    line.textContent = lines[i];
    node.appendChild(line);
  }
}

function say(text) { writeLines("st", text); }
function note(text) { writeLines("sub", text || ""); }
function warn(text) { writeLines("warn", text || ""); }
function diag(text) { el("diag").textContent = text || ""; }

function pct(fraction, label) {
  var width = Math.max(0, Math.min(1, fraction || 0)) * 800;
  el("fill").setAttribute("width", String(width));
  el("pct").textContent = label || (Math.round((fraction || 0) * 100) + "%");
}

function bytes(n) {
  if (!isFinite(n) || n <= 0) return "0 B";
  var units = ["B", "KB", "MB", "GB", "TB"], i = 0;
  while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
  return (n >= 10 || i === 0 ? n.toFixed(0) : n.toFixed(1)) + " " + units[i];
}

// ---- the vault, the same stores launch-sw.js reads --------------------------------
var database = null;

function db() {
  if (database) return Promise.resolve(database);
  return new Promise(function (resolve, reject) {
    var request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = function () {
      var opened = request.result;
      if (!opened.objectStoreNames.contains("meta")) opened.createObjectStore("meta");
      if (!opened.objectStoreNames.contains("chunks")) opened.createObjectStore("chunks");
    };
    request.onsuccess = function () { database = request.result; resolve(database); };
    request.onerror = function () { reject(request.error); };
  });
}

function getMeta() {
  return db().then(function (opened) {
    return new Promise(function (resolve, reject) {
      var request = opened.transaction("meta", "readonly").objectStore("meta").get("game");
      request.onsuccess = function () { resolve(request.result || null); };
      request.onerror = function () { reject(request.error); };
    });
  });
}

function put(store, key, value) {
  return db().then(function (opened) {
    return new Promise(function (resolve, reject) {
      var transaction = opened.transaction(store, "readwrite");
      transaction.objectStore(store).put(value, key);
      transaction.oncomplete = function () { resolve(); };
      transaction.onerror = function () { reject(transaction.error); };
      transaction.onabort = function () { reject(transaction.error); };
    });
  });
}

function wipe() {
  return db().then(function (opened) {
    return new Promise(function (resolve, reject) {
      var transaction = opened.transaction(["meta", "chunks"], "readwrite");
      transaction.objectStore("meta").clear();
      transaction.objectStore("chunks").clear();
      transaction.oncomplete = function () { resolve(); };
      transaction.onerror = function () { reject(transaction.error); };
    });
  });
}

// ---- the worker -------------------------------------------------------------------
function askBuild(worker) {
  return new Promise(function (resolve) {
    if (!worker) { resolve(""); return; }
    var channel = new MessageChannel(), settled = false;
    var timer = setTimeout(function () { if (!settled) { settled = true; resolve(""); } }, 1500);
    channel.port1.onmessage = function (event) {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(String(event.data || ""));
    };
    try { worker.postMessage({ q: "build" }, [channel.port2]); }
    catch (e) { if (!settled) { settled = true; clearTimeout(timer); resolve(""); } }
  });
}

async function ensureWorker() {
  if (!isSecureContext) throw new Error("This page is not a secure context. Serve it over https:// (localhost counts) so it can register its worker.");
  if (!("serviceWorker" in navigator)) throw new Error("This browser has no service worker support. Use OPEN DIRECTLY: the game runs without workers, a little slower.");
  var registration = await navigator.serviceWorker.register(SW_URL + "?v=" + SW_BUILD, {
    scope: "./",
    updateViaCache: "none",
  });
  await navigator.serviceWorker.ready;
  try { await registration.update(); } catch (e) { /* a cached worker still runs */ }
  if (!navigator.serviceWorker.controller) {
    await Promise.race([
      new Promise(function (resolve) { navigator.serviceWorker.addEventListener("controllerchange", resolve, { once: true }); }),
      sleep(3000),
    ]);
  }
  if (!navigator.serviceWorker.controller) {
    throw new Error("The launcher worker did not take control of this page. Reload and try again.");
  }
  var active = registration.active || registration.waiting || registration.installing;
  var got = await askBuild(active);
  diag("worker " + (got || "unknown") + " - expected " + SW_BUILD + " - " + location.origin);
  if (got && got !== SW_BUILD) {
    var key = "horizon-launcher-update";
    if (sessionStorage.getItem(key) !== SW_BUILD) {
      sessionStorage.setItem(key, SW_BUILD);
      try { await registration.unregister(); } catch (e) { /* reload anyway */ }
      location.reload();
      await new Promise(function () {});
    }
    throw new Error("An older launcher worker is still installed. Reload this page: the stale copy was just dropped.");
  }
  return registration;
}

async function spaceFor(need) {
  if (!navigator.storage || !navigator.storage.estimate) return;
  try {
    if (navigator.storage.persist) await navigator.storage.persist();
    var estimate = await navigator.storage.estimate();
    var quota = estimate.quota || 0;
    var free = quota - (estimate.usage || 0);
    if (need && quota && free < need * 1.08) {
      throw new Error("This origin may store " + bytes(free) + " more and the game needs " + bytes(need) +
                      ". Free some browser storage, or use OPEN DIRECTLY.");
    }
  } catch (e) {
    if (e && e.message && e.message.indexOf("may store") >= 0) throw e;
  }
}

// ---- installing -------------------------------------------------------------------
async function install() {
  if (busy) return;
  busy = true;
  el("go").classList.add("off");
  el("golabel").textContent = "WORKING";
  warn("");
  try {
    say("Checking the launcher worker...");
    note("the worker gives the game its threads");
    var registration = await ensureWorker();
    diag("worker " + SW_BUILD + " - " + (registration.active ? "active" : "pending") + " - " + location.origin);

    var total = 0;
    try {
      var head = await fetch(SOURCE, { method: "HEAD", cache: "no-store" });
      if (head.headers.get("content-length")) total = Number(head.headers.get("content-length"));
    } catch (e) { /* a host without HEAD still downloads: progress stays in bytes */ }
    if (!total) {
      try {
        var probe = await fetch(SOURCE, { cache: "no-store" });
        if (!probe.ok) throw new Error(String(probe.status));
        total = Number(probe.headers.get("content-length") || 0);
        var probeReader = probe.body && probe.body.getReader();
        if (probeReader) {
          var first = await probeReader.read();
          if (!first.done) {
            var text = new TextDecoder().decode(first.value.slice(0, 200)).toLowerCase();
            if (text.replace(/^\uFEFF/, "").replace(/^\s+/, "").indexOf("<!doctype html") !== 0 &&
                text.replace(/^\s+/, "").indexOf("<html") !== 0) {
              throw new Error("What arrived is not an HTML document. Check that " + SOURCE + " is the single file.");
            }
          }
          try { await probeReader.cancel(); } catch (e) { /* already closed */ }
        }
      } catch (e) {
        throw new Error("Cannot read " + SOURCE + " (" + e.message + "). Put horizon.html beside launch.svg, or pass ?src=.");
      }
    }
    await spaceFor(total);
    await wipe();

    var have = 0, chunks = 0, offset = 0, attempts = 0;
    var buffer = new Uint8Array(CHUNK);
    var headText = "";
    var started = Date.now(), lastTick = 0;

    async function flush() {
      if (!offset) return;
      var piece = new Blob([buffer.slice(0, offset)]);
      var at = chunks;
      chunks += 1;
      offset = 0;
      buffer = new Uint8Array(CHUNK);
      await put("chunks", at, piece);
    }

    say(total ? "Downloading " + bytes(total) : "Downloading the game");
    note(SOURCE);
    for (;;) {
      var response;
      try {
        response = await fetch(SOURCE, {
          headers: have ? { Range: "bytes=" + have + "-" } : {},
          cache: "no-store",
        });
      } catch (e) {
        attempts += 1;
        if (attempts > 4) throw new Error("The download stopped (" + e.message + "). Check that " + SOURCE + " is reachable.");
        say("Connection lost, retrying...");
        await sleep(700 * attempts);
        continue;
      }
      if (!response.ok) {
        if (response.status === 404) throw new Error("horizon.html was not found beside launch.svg. Put the single file here, or open launch.svg?src=...");
        throw new Error(SOURCE + " answered " + response.status + " " + response.statusText + ".");
      }
      if (have && response.status !== 206) {
        await wipe();
        have = 0;
        chunks = 0;
        offset = 0;
        buffer = new Uint8Array(CHUNK);
      }
      var reader = response.body && response.body.getReader();
      if (!reader) {
        var all = new Uint8Array(await response.arrayBuffer());
        if (headText.length < 200) headText += new TextDecoder().decode(all.slice(0, 200 - headText.length));
        var at = 0;
        while (at < all.length) {
          var take = Math.min(CHUNK - offset, all.length - at);
          buffer.set(all.subarray(at, at + take), offset);
          offset += take;
          at += take;
          have += take;
          if (offset === CHUNK) await flush();
        }
      } else {
        for (;;) {
          var step = await reader.read();
          if (step.done) break;
          var value = step.value;
          if (headText.length < 200) {
            headText += new TextDecoder().decode(value.slice(0, 200 - headText.length));
          }
          var pos = 0;
          while (pos < value.length) {
            var amount = Math.min(CHUNK - offset, value.length - pos);
            buffer.set(value.subarray(pos, pos + amount), offset);
            offset += amount;
            pos += amount;
            have += amount;
            if (offset === CHUNK) await flush();
          }
          var now = Date.now();
          if (now - lastTick > 120) {
            lastTick = now;
            var rate = have / Math.max(1, now - started) * 1000;
            pct(total ? have / total : 0, total ? Math.round(have / total * 100) + "%" : bytes(have));
            note(bytes(have) + (total ? " of " + bytes(total) : "") + "  -  " + bytes(rate) + "/s");
          }
        }
      }
      if (total && have < total) {
        attempts += 1;
        if (attempts > 5) throw new Error("The download stalled at " + bytes(have) + " of " + bytes(total) + ".");
        say("Reconnecting at " + bytes(have) + "...");
        await sleep(600 * attempts);
        continue;
      }
      break;
    }
    await flush();
    var signature = headText.replace(/^\uFEFF/, "").replace(/^\s+/, "").toLowerCase();
    if (signature.indexOf("<!doctype html") !== 0 && signature.indexOf("<html") !== 0) {
      throw new Error("What arrived is not an HTML document. Check that " + SOURCE + " is the single file.");
    }
    await put("meta", "game", {
      size: have,
      chunks: chunks,
      name: "horizon.html",
      source: SOURCE,
      storedAt: Date.now(),
    });
    pct(1, "100%");
    say("Ready - " + bytes(have));
    note("the worker serves it cross-origin isolated");
    el("golabel").textContent = "LAUNCH";
    busy = false;
    el("go").classList.remove("off");
  } catch (e) {
    fail(e);
  }
}

function fail(error) {
  say("Stopped");
  var message = error && error.message ? error.message : String(error);
  note(message);
  warn(message);
  el("golabel").textContent = "RETRY";
  el("go").classList.remove("off");
  busy = false;
}

// ---- launching --------------------------------------------------------------------
async function launch() {
  if (busy) return;
  busy = true;
  warn("");
  try {
    say("Launching...");
    note("the worker serves it cross-origin isolated");
    await ensureWorker();
    var target = new URL("__horizon.html", location.href);
    var args = Q.get("args");
    if (args) target.searchParams.set("args", args);
    location.replace(target.href);
    await new Promise(function () {});
  } catch (e) {
    fail(e);
  }
}

function sameSource(meta) {
  return !meta || !meta.source || meta.source === SOURCE;
}

async function start() {
  var meta = await getMeta().catch(function () { return null; });
  if (meta && meta.size && sameSource(meta)) return launch();
  await install();
  if (Q.get("autostart") === "1") {
    var installed = await getMeta().catch(function () { return null; });
    if (installed && installed.size && sameSource(installed)) return launch();
  }
}

function direct() {
  say("Opening without workers...");
  note("the single-threaded build; the game still runs");
  location.href = SOURCE;
}

async function clear() {
  if (busy) return;
  busy = true;
  try {
    await wipe();
    pct(0, "0%");
    say("Storage cleared");
    note("press DOWNLOAD to install it again");
    el("golabel").textContent = "DOWNLOAD";
    warn("");
  } catch (e) {
    fail(e);
  }
  busy = false;
}

async function refresh() {
  var meta = await getMeta().catch(function () { return null; });
  var parts = [
    location.origin,
    "secure " + (isSecureContext ? "yes" : "no"),
    "worker " + (navigator.serviceWorker ? "yes" : "no"),
    "vault " + (meta && meta.size ? bytes(meta.size) : "empty"),
  ];
  diag(parts.join("  -  "));
  if (meta && meta.size && sameSource(meta)) {
    el("golabel").textContent = "LAUNCH";
    say("Ready - " + bytes(meta.size));
    note(meta.name || "horizon.html");
    pct(1, "100%");
  } else {
    el("golabel").textContent = "DOWNLOAD";
    say("Not installed yet");
    note("downloads " + SOURCE);
    pct(0, "0%");
  }
  if (!isSecureContext || !navigator.serviceWorker) {
    warn("This page cannot use a service worker. OPEN DIRECTLY runs the game without workers.");
  }
}

function wireButton(id, action) {
  var node = el(id);
  node.addEventListener("click", function () { action(); });
  node.addEventListener("keydown", function (event) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      action();
    }
  });
}

function wire() {
  wireButton("go", function () { start(); });
  wireButton("direct", direct);
  wireButton("clr", function () { clear(); });
}

(async function boot() {
  wire();
  if (Q.get("reset") === "1") await wipe().catch(function () {});
  await refresh();
  if (Q.get("autostart") === "1") await start();
})().catch(function (e) {
  say("Stopped");
  note(e && e.message ? e.message : String(e));
  warn(e && e.message ? e.message : String(e));
});

// Handy from a browser console while testing the launcher.
globalThis.horizonLauncher = { install: install, launch: launch, clear: clear, refresh: refresh, source: SOURCE };
